// Writes skill/files.generated.ts from the real skill files, so the admin's zip can't drift from them.
// Run: pnpm skill:gen   (a Jest test fails when the generated file is stale)
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = dirname(fileURLToPath(import.meta.url))
const names = ['SKILL.md', 'beitecha.py', 'README.md']
const body = names
  .map((n) => `  ${JSON.stringify(n)}: ${JSON.stringify(readFileSync(join(dir, n), 'utf8'))},`)
  .join('\n')
const out = `// Generated by skill/gen.mjs (pnpm skill:gen). Do not edit.\nexport const SKILL_FILES: Record<string, string> = {\n${body}\n}\n`
writeFileSync(join(dir, 'files.generated.ts'), out)
